{
  "schema_version": "0.1.0",
  "proposal_id": "mp-bc003-s12-hypothesis-001",
  "proposal_type": "PROVIDE_BOUNDED_HYPOTHESIS",
  "rationale": "The rollout-health gate is FAILED and the rollout is PAUSED (BC003-R1). The authoritative capacity findings (BC003-R4) establish that 6 stable replicas fail the <90% utilization check at 820 RPS (91.1%), and 7 replicas fail the N-1 tolerance requirement; 8 replicas pass both. All rollback preconditions (DB compatibility, config compatibility, dependency headroom, no conflicting operations) are confirmed. The bounded remediation path therefore consists of scaling the stable version to the minimum compliant count of 8 and rolling back the degraded candidate version. This is an assessment and proposal only; it does not authorize execution (P001) and no action-bound confirmation is requested from the EVIDENCE_EVALUATED state (BC003-R5).",
  "payload": {
    "hypotheses": [
      {
        "hypothesis_id": "hyp-bc003-remediate-rollback-scale-001",
        "statement": "The single bounded remediation path is: (1) scale stable-version 2.4.1 from the current 6 healthy replicas to the authoritative minimum compliant count of 8 replicas so that projected utilization at 820 RPS drops to ≤78.1% and the group tolerates N-1 while remaining below the 90% threshold (BC003-R2, BC003-R3); and (2) roll back candidate-version 2.4.2 by terminating its 2 degraded replicas and shifting all production traffic to stable 2.4.1, which is permitted because DB and configuration compatibility with 2.4.1 are CONFIRMED, dependency headroom is PASS, and no conflicting rollout/restart/rollback operation exists. The rollout remains PAUSED per the FAILED health-gate result (BC003-R1). This proposal does not authorize execution (P001).",
        "source": "DETERMINISTIC_RULE",
        "cause_status": "SUPPORTED",
        "evidence_ids": [
          "ev-bc003-rollout-health",
          "ev-bc003-capacity-findings",
          "ev-bc003-capacity-policy",
          "ev-bc003-rollback-compatibility",
          "ev-bc003-dependency-headroom",
          "ev-bc003-operation-conflicts",
          "ev-bc003-rollout-topology"
        ],
        "missing_evidence": []
      }
    ]
  }
}

